// Package target holds what each DNS provider can serve, so lint can say what will not survive a move to it (model
// section 3, L-01 to L-03). The data is DNSControl's provider feature matrix at a pinned release, generated by
// tools/capabilities.py into dnscontrol.json, plus Lostname's own observations with their source.
package target

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

//go:embed dnscontrol.json
var raw []byte

// Support is a provider's support for one record type: "yes", "no" or "unknown".
type Support string

const (
	Yes     Support = "yes"
	No      Support = "no"
	Unknown Support = "unknown"
)

// Source says where the capability data comes from.
type Source struct {
	Project  string `json:"project"`
	Tag      string `json:"tag"`
	Commit   string `json:"commit"`
	Released string `json:"released"` // the release date, YYYY-MM-DD
	Path     string `json:"path"`
}

type file struct {
	Schema    string                       `json:"schema"`
	Source    Source                       `json:"source"`
	Providers map[string]map[string]string `json:"providers"`
}

// Provider is one target.
type Provider struct {
	Name     string
	features map[string]string
}

// data is loaded in a variable initialiser, not in init(), so that listed (which depends on it) sees it: Go
// initialises package variables in dependency order before any init function runs.
var data = func() file {
	var f file
	if err := json.Unmarshal(raw, &f); err != nil || f.Schema != "lostname.capabilities/v0" || len(f.Providers) == 0 {
		panic(fmt.Sprintf("target: the embedded capability data is unreadable (%v); regenerate it with tools/capabilities.py", err))
	}
	return f
}()

// From returns where the data comes from, for findings and reports.
func From() Source { return data.Source }

// Lookup returns the provider by its DNSControl name (case-insensitive), or an error that lists the known names.
func Lookup(name string) (Provider, error) {
	n := strings.ToUpper(name)
	if f, ok := data.Providers[n]; ok {
		return Provider{Name: n, features: f}, nil
	}
	names := make([]string, 0, len(data.Providers))
	for k := range data.Providers {
		names = append(names, k)
	}
	sort.Strings(names)
	return Provider{}, fmt.Errorf("unknown provider %q; DNSControl %s knows: %s", name, data.Source.Tag,
		strings.Join(names, ", "))
}

// Supports says whether the provider serves records of type t. Types the matrix does not list are supported
// everywhere; a type the matrix lists but this provider's row leaves out is unknown.
func (p Provider) Supports(t string) Support {
	if !listed[t] {
		return Yes
	}
	switch Support(p.features[t]) {
	case Yes:
		return Yes
	case No:
		return No
	}
	return Unknown
}

// Feature is the provider's support for a feature column of the matrix that is not a record type (AUTODNSSEC):
// unknown when the row leaves it out.
func (p Provider) Feature(name string) Support {
	switch Support(p.features[name]) {
	case Yes:
		return Yes
	case No:
		return No
	}
	return Unknown
}

// NeedsSOA returns why the provider needs an SOA in the config, or "".
func (p Provider) NeedsSOA() string { return p.features["_needs_soa"] }

// listed are the record types the matrix has a column for.
var listed = func() map[string]bool {
	m := map[string]bool{}
	for _, f := range data.Providers {
		for k := range f {
			if !strings.HasPrefix(k, "_") && k != "AUTODNSSEC" {
				m[k] = true
			}
		}
	}
	return m
}()
